import {createWorld,places,anchors} from './scene.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,world,entered=false,activePlace='street',returnFocus=null,audioCtx=null,audioTimer=null,audioOn=false,toastTimer;
let state={collected:[],reflection:'',level:'explore',quiz:[],time:'day'};
try{const saved=JSON.parse(localStorage.getItem('assembl-pompeii-v1')||'null');if(saved&&Array.isArray(saved.collected))state={...state,...saved};}catch{}
const save=()=>{try{localStorage.setItem('assembl-pompeii-v1',JSON.stringify(state));}catch{toast('Your browser could not save notes. Use Export to keep a copy.');}};
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function completeLoading(){$('#loading').classList.add('loaded');setTimeout(()=>$('#loading').hidden=true,700);}
function fallback(){document.body.classList.add('reader-mode');completeLoading();const warn=document.createElement('div');warn.className='warning-banner';warn.textContent='3D is unavailable on this device. You can still explore every evidence stop, collect notes and complete the investigation.';document.body.append(warn);$('#scene-mode').textContent='Reading mode · all learning activities available';}
try{data=await fetch('evidence.json').then(r=>{if(!r.ok)throw Error('Evidence unavailable');return r.json()});}catch(e){completeLoading();$('#intro').innerHTML='<h1>The field notes<br>could not load.</h1><p>Please refresh the page to try again.</p><button class="primary" onclick="location.reload()">Reload</button>';throw e;}
try{world=createWorld($('#scene'),completeLoading);}catch(e){console.warn('3D unavailable',e);fallback();}
document.addEventListener('scene-lost',fallback);
function updateCount(){$('#count').textContent=state.collected.length;document.querySelectorAll('.hotspot').forEach(el=>{const yes=state.collected.includes(el.dataset.evidence);el.classList.toggle('collected',yes);el.querySelector('.hot-dot').textContent=yes?'✓':'+';});}
for(const ev of data.hotspots){const b=document.createElement('button');b.className='hotspot';b.dataset.evidence=ev.id;b.hidden=true;b.setAttribute('aria-label','Inspect '+ev.title);b.innerHTML=`<span class="hot-dot">+</span><span class="hot-label">${esc({crossing:'The crossing',counter:'Food & drink',mill:'The grain mill',water:'Follow the rain',fresco:'Painted walls',amphora:'A jar with a journey'}[ev.id])}</span>`;b.onclick=()=>showEvidence(ev.id);$('#hotspots').append(b);}
updateCount();
function enter(id='street'){
  entered=true;activePlace=id;document.body.classList.add('exploring');$('#intro').classList.add('leaving');setTimeout(()=>$('#intro').hidden=true,650);$('#place-card').classList.remove('hidden');if(world)$('#walk-controls').classList.remove('hidden');
  const p=places[id];$('#place-title').textContent=p.title;$('#place-number').textContent=p.number;$('#place-description').textContent=p.description;$('#place-clue').onclick=()=>showEvidence(p.clue);document.querySelectorAll('[data-place]').forEach(el=>{el.classList.toggle('active',el.dataset.place===id);if(el.tagName==='BUTTON')el.setAttribute('aria-pressed',el.dataset.place===id)});world?.go(id);
}
$('#enter').onclick=()=>enter();document.querySelectorAll('[data-place]').forEach(el=>{el.addEventListener('click',()=>enter(el.dataset.place));if(el.tagName.toLowerCase()==='g')el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();enter(el.dataset.place);}})});
$('#overview').onclick=()=>{if(!entered)enter();world?.overview();toast('Aerial view · select a place to return to street level');};
$('#cutaway').onclick=()=>{if(!world)return toast('Roof controls need the 3D view.');const off=world.toggleRoof();$('#cutaway').innerHTML=`<span>◈</span> ${off?'Roofs off':'Roofs on'}`;$('#cutaway').setAttribute('aria-pressed',String(off));$('#scene-mode').textContent=off?'Cutaway · the same interpretive model':'An interpretive 3D reconstruction';};
$('#map-toggle').onclick=()=>{const collapsed=$('#map-card').classList.toggle('collapsed');$('#map-toggle').textContent=collapsed?'+':'−';$('#map-toggle').setAttribute('aria-label',collapsed?'Expand map':'Collapse map')};
function drawer(kicker,html){if($('#drawer').hidden)returnFocus=document.activeElement;$('#drawer-kicker').textContent=kicker;$('#drawer-content').innerHTML=html;$('#drawer').hidden=false;$('#scrim').hidden=false;$('#drawer').scrollTop=0;$('#close-drawer').focus();}
function closeDrawer(){$('#drawer').hidden=true;$('#scrim').hidden=true;returnFocus?.focus?.();}
$('#close-drawer').onclick=closeDrawer;$('#scrim').onclick=closeDrawer;
addEventListener('keydown',e=>{if($('#drawer').hidden)return;if(e.key==='Escape')closeDrawer();if(e.key==='Tab'){const focusable=Array.from($('#drawer').querySelectorAll('button:not([disabled]),a,input,textarea,select,summary,[tabindex="0"]'));const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
function showEvidence(id){const ev=data.hotspots.find(e=>e.id===id);if(!ev)return;const has=state.collected.includes(id);
 drawer('EVIDENCE / '+String(data.hotspots.indexOf(ev)+1).padStart(2,'0'),`<span class="evidence-status">${esc(ev.evidenceType)}</span><h2 id="drawer-title" style="margin-top:18px">${esc(ev.title)}</h2><p class="lede">${esc(ev.documented)}</p><div class="inference-box"><span>WHAT WE CAN INFER</span><p>${esc(ev.interpretation)}</p></div><a class="source-link" href="${ev.sourceUrl}" target="_blank" rel="noopener">Read the source ↗<br>${esc(ev.sourceLabel)}</a>${ev.additionalSources?.map(s=>`<a class="source-link" href="${s.url}" target="_blank" rel="noopener">${esc(s.label)} ↗</a>`).join('')||''}<div class="question-box">${esc(ev.question)}</div><button id="collect" class="primary" ${has?'disabled':''}>${has?'✓ Saved in your field notes':'Add to field notes + '}</button><p class="small-note">The object and setting shown here are illustrative. The linked archaeology supports the written evidence, not every visual detail.</p><div class="two-buttons"><button class="secondary" id="back-scene">Return to Pompeii</button><button class="secondary" id="next-evidence">Next discovery →</button></div>`);
 $('#collect').onclick=()=>{if(!state.collected.includes(id))state.collected.push(id);save();updateCount();$('#collect').textContent='✓ Saved in your field notes';$('#collect').disabled=true;toast('Evidence added to your field notes');};$('#back-scene').onclick=closeDrawer;$('#next-evidence').onclick=()=>{const next=data.hotspots[(data.hotspots.indexOf(ev)+1)%data.hotspots.length];const loc={crossing:'street',counter:'counter',mill:'bakery',water:'courtyard',fresco:'courtyard',amphora:'counter'}[next.id];closeDrawer();enter(loc);setTimeout(()=>showEvidence(next.id),world?1900:0);};
}
function showNotebook(){drawer('YOUR FIELD NOTES',`<h2 id="drawer-title">Small clues.<br>Bigger stories.</h2><p>${state.collected.length} of 6 discoveries collected. Your notes are saved in this browser.</p>${state.collected.length?state.collected.map(id=>{const ev=data.hotspots.find(e=>e.id===id);return ev?`<article class="field-card"><div class="eyebrow">${esc(ev.evidenceType)}</div><h3>${esc(ev.title)}</h3><p>${esc(ev.takeaway)}</p><button data-read="${id}">Open evidence & source ↗</button></article>`:''}).join(''):'<div class="empty-notes"><span class="badge">YOUR NOTEBOOK IS READY</span><p>Choose a place, inspect a glowing evidence marker and save a discovery here.</p><button id="first-discovery" class="primary">Find your first clue →</button></div>'}<h3>${esc(data.reflection.prompt)}</h3><p>${esc(data.reflection.instructions)}</p><label for="reflection" class="step-label">YOUR HISTORICAL ARGUMENT</label><textarea id="reflection" placeholder="My claim is…\nThe evidence from… suggests…\nA different experience is shown by…\nOne limitation is…">${esc(state.reflection)}</textarea><div class="saved-note" id="save-status">Saved on this device</div><p class="small-note">${esc(data.reflection.feedback)}</p><div class="two-buttons"><button class="secondary" id="export">Export notes ↓</button><button class="secondary" id="print">Print / PDF</button></div><button class="primary" id="notes-mission">Continue the investigation →</button><details><summary>Manage this notebook</summary><p>Clearing removes discoveries, quiz answers and writing from this browser.</p><button class="secondary" id="reset">Clear my notes</button></details>`);
 document.querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>showEvidence(b.dataset.read));$('#first-discovery')?.addEventListener('click',()=>{closeDrawer();enter('street');showEvidence('crossing');});$('#reflection').oninput=e=>{state.reflection=e.target.value;save();$('#save-status').textContent='Saved just now on this device';};$('#export').onclick=exportNotes;$('#print').onclick=()=>print();$('#notes-mission').onclick=showMission;$('#reset').onclick=()=>{drawer('RESET NOTEBOOK',`<h2 id="drawer-title">Start fresh?</h2><p>This clears your six discoveries, answers and reflection from this browser. Export a copy first if you want to keep your work.</p><button class="primary" id="confirm-reset">Clear my notes</button><button class="secondary" id="cancel-reset" style="margin-top:12px;width:100%">Keep my notes</button>`);$('#confirm-reset').onclick=()=>{state.collected=[];state.reflection='';state.quiz=[];save();updateCount();showNotebook();};$('#cancel-reset').onclick=showNotebook;};
}
$('#notebook').onclick=showNotebook;
function exportNotes(){let text=`# Pompeii · assembl lab\n\n## My investigation\n${data.mission}\n\n## Discoveries\n\n`;
 state.collected.forEach(id=>{const e=data.hotspots.find(v=>v.id===id);if(e)text+=`### ${e.title}\n\nEvidence: ${e.documented}\n\nInterpretation: ${e.interpretation}\n\nSource: ${e.sourceLabel}\n${e.sourceUrl}\n\n`;});text+=`## My argument\n\n${state.reflection||'(Not written yet)'}\n\n## Learning check\n${state.quiz.filter((a,i)=>a===data.assessment[i]?.correct).length} of ${data.assessment.length} correct on the last attempt.\n\n## About the reconstruction\n${data.sceneLabel}\n${data.status}\n`;
 const blob=new Blob([text],{type:'text/markdown;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='pompeii-field-notes.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your field notes have been exported');}
function showMission(){const needed=['counter','mill','water'],done=needed.filter(id=>state.collected.includes(id)).length;
 drawer('THE INVESTIGATION',`<span class="badge">ABOUT 10 MINUTES · EVIDENCE, NOT GUESSWORK</span><h2 id="drawer-title">Who had comfort?<br>Who did the work?</h2><p class="lede">${esc(data.mission)}</p><div class="progress-dots">${needed.map(id=>`<span class="${state.collected.includes(id)?'done':''}"></span>`).join('')}</div><div class="step-label">STEP 01 / FOLLOW THREE DIFFERENT LIVES</div>${needed.map((id,i)=>{const e=data.hotspots.find(x=>x.id===id);return `<article class="field-card"><div class="eyebrow">${state.collected.includes(id)?'✓ EVIDENCE COLLECTED':String(i+1).padStart(2,'0')+' / TO DISCOVER'}</div><h3>${esc(e.title)}</h3><button data-discover="${id}">Explore this evidence →</button></article>`}).join('')}<h3>Choose your question depth</h3><div class="two-buttons"><button class="secondary ${state.level==='explore'?'selected':''}" id="level-explore" aria-pressed="${state.level==='explore'}">Explore</button><button class="secondary ${state.level==='analyse'?'selected':''}" id="level-analyse" aria-pressed="${state.level==='analyse'}">Analyse</button></div><p id="level-description">${state.level==='analyse'?'Compare evidence from different contexts, question the interpretation and explain whose perspective is missing.':'Identify what objects did, compare a home and a workplace, and explain one difference.'}</p><div class="step-label" style="margin-top:25px">STEP 02 / CHECK YOUR UNDERSTANDING</div><button class="primary" id="start-quiz" ${done<3?'disabled':''}>${done<3?`Collect ${3-done} more key ${3-done===1?'clue':'clues'} to continue`:'Start the 3-question check →'}</button><div class="step-label" style="margin-top:25px">STEP 03 / MAKE YOUR ARGUMENT</div><p>${state.level==='analyse'?'How far can these buildings and objects support a claim about inequality? Explain two inferences, a limitation, and what further evidence you would seek.':esc(data.reflection.instructions)}</p><button class="secondary" id="write-argument">Write in your field notes →</button><p class="small-note">Designed for historical enquiry. This prototype has not been mapped to a specific curriculum or NCEA assessment standard.</p>`);
 document.querySelectorAll('[data-discover]').forEach(b=>b.onclick=()=>{const id=b.dataset.discover;closeDrawer();enter({counter:'counter',mill:'bakery',water:'courtyard'}[id]);setTimeout(()=>showEvidence(id),world?1900:0);});
 for(const level of ['explore','analyse'])$('#level-'+level).onclick=()=>{state.level=level;save();showMission();};$('#start-quiz').onclick=()=>showQuiz(0);$('#write-argument').onclick=showNotebook;
}
$('#mission').onclick=showMission;$('#intro-mission').onclick=showMission;
function showQuiz(index){const q=data.assessment[index],answer=state.quiz[index];drawer('LEARNING CHECK / '+(index+1)+' OF 3',`<div class="progress-dots">${data.assessment.map((_,i)=>`<span class="${i<=index?'done':''}"></span>`).join('')}</div><h2 id="drawer-title" style="font-size:30px">${esc(q.question)}</h2><div id="quiz-options">${q.options.map((o,i)=>`<button class="quiz-option" data-answer="${i}">${String.fromCharCode(65+i)} &nbsp; ${esc(o)}</button>`).join('')}</div><div id="quiz-result"></div><button class="primary" id="quiz-next" hidden>${index===2?'Review your investigation →':'Next question →'}</button><button class="text-button" id="quiz-source" style="margin-top:14px">Revisit the evidence ↗</button>`);
 document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const chosen=Number(b.dataset.answer);state.quiz[index]=chosen;save();document.querySelectorAll('[data-answer]').forEach(o=>{o.disabled=true;o.classList.toggle('correct',Number(o.dataset.answer)===q.correct);o.classList.toggle('incorrect',Number(o.dataset.answer)===chosen&&chosen!==q.correct);});$('#quiz-result').innerHTML=`<div class="quiz-feedback"><strong>${chosen===q.correct?'Supported by the evidence.':'A useful distinction to notice.'}</strong><p>${esc(q.explanation)}</p></div>`;$('#quiz-next').hidden=false;});$('#quiz-next').onclick=()=>index<2?showQuiz(index+1):showQuizResult();$('#quiz-source').onclick=()=>showEvidence(q.evidenceId);
}
function showQuizResult(){let score=state.quiz.filter((a,i)=>a===data.assessment[i]?.correct).length;drawer('YOUR INVESTIGATION',`<span class="badge">LEARNING CHECK COMPLETE</span><h2 id="drawer-title">Now tell the story<br>with evidence.</h2><p class="lede">${score} of 3 answers supported by the sources.</p><p>History asks us to do more than remember a fact. Connect what you found in the home, food counter and bakery, and explain what remains uncertain.</p><ul class="checklist"><li>Name at least two pieces of evidence.</li><li>Explain how each supports your claim.</li><li>Include one limitation or unanswered question.</li></ul><button class="primary" id="finish-writing">Write your argument →</button><button class="secondary" id="retry-quiz" style="margin-top:12px;width:100%">Try the questions again</button>`);$('#finish-writing').onclick=showNotebook;$('#retry-quiz').onclick=()=>{state.quiz=[];save();showQuiz(0);};}
function showSources(){drawer('SOURCES & RECONSTRUCTION',`<h2 id="drawer-title">How do we know?</h2><p class="lede">This neighbourhood is newly modelled. The archaeology behind its learning stops is real.</p><div class="inference-box"><span>WHAT YOU ARE EXPLORING</span><p>${esc(data.sceneLabel)} Buildings, objects, colours and their arrangement are illustrative.</p></div><p>The experience uses interactive WebGL geometry. It does not contain a photographic Gaussian-splat scan. A cutaway removes the roofs from this model; it is not a present-day excavation view.</p>${data.hotspots.map(e=>`<div class="source-item"><a href="${e.sourceUrl}" target="_blank" rel="noopener">${esc(e.title)} ↗</a><p>${esc(e.sourceLabel)}</p><small>${esc(e.evidenceType)}</small></div>`).join('')}<div class="source-item"><a href="https://tapestry.cyark.org/content/pompeii-forum" target="_blank" rel="noopener">Compare with the surviving Forum ↗</a><p>External CyArk experience of the real site. Its scans are not included in this reconstruction.</p></div><h3>Keep the uncertainties visible</h3><p>${esc(data.status)}</p><p>We do not invent exact prices, personal biographies or a precise eruption date. The mill movement, water and sound are illustrative animation and sound design, not historical recordings or physical simulations.</p><p class="small-note">Sources checked 26 October 2026. Written summaries and 3D assets authored for assembl lab. Three.js is used under the MIT licence. No source photographs or scans have been copied.</p><button class="primary" id="source-guide">Open the source guide →</button>`);$('#source-guide').onclick=showGuide;}
$('#sources').onclick=showSources;
function showGuide(){drawer('SOURCE GUIDE',`<h2 id="drawer-title">Let curiosity<br>lead the way.</h2><p>Choose a question to open its researched evidence. This is a curated guide, not an AI conversation.</p>${data.hotspots.map(e=>`<button class="guide-question" data-guide="${e.id}">${esc(e.question)} <span>↗</span></button>`).join('')}<button class="secondary" id="guide-back" style="margin-top:20px">Back to the sources</button>`);document.querySelectorAll('[data-guide]').forEach(b=>b.onclick=()=>showEvidence(b.dataset.guide));$('#guide-back').onclick=showSources;}
function showHelp(){drawer('YOUR FIELD TRIP',`<h2 id="drawer-title">Take a closer look.</h2><p class="lede">Move at your own pace. Every discovery has a source and a question.</p><ul class="checklist"><li>Choose one of the four places along the bottom.</li><li>Drag the scene to look around.</li><li>Use W A S D, arrow keys or the onscreen arrows to move.</li><li>Tap a + marker to inspect evidence.</li><li>Switch roofs off to see inside the buildings.</li><li>Save discoveries in your field notes.</li></ul><h3>Atmosphere</h3><p class="small-note">Change the light. These are visual settings, not reconstructed historical times.</p><div class="atmosphere">${['morning','day','evening'].map(t=>`<button data-time="${t}" class="${state.time===t?'active':''}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><h3>Performance</h3><div class="two-buttons"><button class="secondary" id="low-detail">Lighter graphics</button><button class="secondary" id="high-detail">Full graphics</button></div><h3>Prefer to read?</h3><p>Every evidence stop and learning activity is also available as text.</p><button class="secondary" id="help-guide">Browse the source guide →</button><button class="primary" id="help-close">Back to Pompeii ↗</button>`);document.querySelectorAll('[data-time]').forEach(b=>b.onclick=()=>{state.time=b.dataset.time;world?.setTime(state.time);save();document.querySelectorAll('[data-time]').forEach(v=>v.classList.toggle('active',v.dataset.time===state.time));});$('#low-detail').onclick=()=>{world?.setQuality(true);toast('Lighter graphics enabled');};$('#high-detail').onclick=()=>{world?.setQuality(false);toast('Full graphics enabled');};$('#help-guide').onclick=showGuide;$('#help-close').onclick=closeDrawer;}
$('#help').onclick=showHelp;
function birds(){if(!audioCtx||!audioOn)return;const now=audioCtx.currentTime;for(let i=0;i<3;i++){const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.setValueAtTime(1700+i*370,now+i*.17);o.frequency.exponentialRampToValueAtTime(2700-i*150,now+i*.17+.09);g.gain.setValueAtTime(0,now+i*.17);g.gain.linearRampToValueAtTime(.014,now+i*.17+.025);g.gain.exponentialRampToValueAtTime(.001,now+i*.17+.16);o.connect(g);g.connect(audioCtx.destination);o.start(now+i*.17);o.stop(now+i*.17+.17);}}
async function toggleAudio(){if(audioOn){audioOn=false;clearInterval(audioTimer);await audioCtx?.suspend();}else{try{if(!audioCtx){audioCtx=new (window.AudioContext||window.webkitAudioContext)();const buffer=audioCtx.createBuffer(1,audioCtx.sampleRate*3,audioCtx.sampleRate),channel=buffer.getChannelData(0);for(let i=0;i<channel.length;i++)channel[i]=(Math.random()*2-1)*.12;const source=audioCtx.createBufferSource();source.buffer=buffer;source.loop=true;const f=audioCtx.createBiquadFilter();f.type='lowpass';f.frequency.value=350;const g=audioCtx.createGain();g.gain.value=.055;source.connect(f);f.connect(g);g.connect(audioCtx.destination);source.start();}await audioCtx.resume();audioOn=true;birds();audioTimer=setInterval(birds,9000);toast('Illustrative ambience on · birds and a soft breeze');}catch{toast('Ambient sound is unavailable in this browser.');return;}}$('#sound').innerHTML=`♫<span>Sound ${audioOn?'on':'off'}</span>`;$('#sound').setAttribute('aria-label',audioOn?'Turn off ambient sound':'Turn on ambient sound');$('#sound').setAttribute('aria-pressed',String(audioOn));}
$('#sound').onclick=toggleAudio;document.addEventListener('visibilitychange',()=>{if(audioOn){if(document.hidden)audioCtx?.suspend();else audioCtx?.resume();}});world?.setTime(state.time);
